package com.chatsystem.admin.controller;

import com.chatsystem.admin.navigation.*; import com.chatsystem.admin.ui.*; import com.chatsystem.admin.ui.cell.AdminUserCell; import com.chatsystem.shared.model.UserAccount; import com.chatsystem.shared.model.status.UserStatus; import com.chatsystem.shared.service.AdminService;
import javafx.collections.*; import javafx.fxml.FXML; import javafx.scene.control.*; import javafx.scene.layout.StackPane; import java.util.*;
public final class UsersController implements DisposableController {
 private final AdminService service;private final AdminNavigator navigator;private final ObservableList<UserAccount> results=FXCollections.observableArrayList();private final javafx.beans.InvalidationListener refreshListener=o->refresh();private String query="";private UserStatus status;private boolean recentLoginOnly;private AdminService.UserSort sort=AdminService.UserSort.RECENT_LOGIN;private int page;private static final int PAGE_SIZE=6;
 @FXML private TextField searchField;@FXML private ListView<UserAccount> userList;@FXML private Label emptyLabel,totalMetric,activeMetric,restrictedMetric;@FXML private Button previousButton,nextButton,downloadButton,addButton;@FXML private MenuButton sortButton,filterButton;@FXML private StackPane downloadWrapper;
 public UsersController(AdminService service,AdminNavigator navigator){this.service=service;this.navigator=navigator;service.getUsers().addListener(refreshListener);service.getUsers().forEach(u->u.statusProperty().addListener(refreshListener));refresh();}
 @FXML private void initialize(){addButton.setOnAction(e->com.chatsystem.admin.ui.AdminAccountDialogs.showEditor(service,null));searchField.textProperty().addListener((o,a,b)->setQuery(b));userList.setItems(results);userList.setCellFactory(v->new AdminUserCell(this::open));previousButton.setOnAction(e->previous());nextButton.setOnAction(e->next());for(var value:AdminService.UserSort.values()){MenuItem item=new MenuItem(label(value));item.setOnAction(e->setSort(value));sortButton.getItems().add(item);}MenuItem all=new MenuItem("All statuses");all.setOnAction(e->{recentLoginOnly=false;setStatus(null);});filterButton.getItems().add(all);for(var value:UserStatus.values()){MenuItem item=new MenuItem(label(value));item.setOnAction(e->{recentLoginOnly=false;setStatus(value);});filterButton.getItems().add(item);}MenuItem recent=new MenuItem("Logged in within 30 days");recent.setOnAction(e->{status=null;recentLoginOnly=true;page=0;refresh();});filterButton.getItems().add(recent);DisabledControlSupport.install(downloadButton,downloadWrapper,"User CSV download is unavailable in the frontend-only demo.");refreshButtons();refreshMetrics();}
 public ObservableList<UserAccount> results(){return FXCollections.unmodifiableObservableList(results);}public void setQuery(String q){query=q==null?"":q;page=0;refresh();}public void setStatus(UserStatus s){status=s;page=0;refresh();}public void setSort(AdminService.UserSort s){sort=Objects.requireNonNull(s);page=0;refresh();}
 public boolean previous(){if(page==0)return false;page--;refresh();return true;}public boolean next(){if((page+1)*PAGE_SIZE>=matching().size())return false;page++;refresh();return true;}public void open(long id){navigator.navigate(ViewRequest.user(id));}
 private java.util.List<UserAccount> matching(){var all=service.searchUsers(query,status,sort,0,Integer.MAX_VALUE);if(!recentLoginOnly)return all;var cutoff=com.chatsystem.shared.mock.MockFixtures.REFERENCE_TIME.minus(30,java.time.temporal.ChronoUnit.DAYS);return all.stream().filter(u->service.getLoginHistory(u.getId()).stream().anyMatch(e->!e.loggedInAt().isBefore(cutoff))).toList();}private void refreshMetrics(){if(totalMetric!=null){var m=service.getMetrics();totalMetric.setText(Long.toString(m.totalUsers()));activeMetric.setText(Long.toString(m.activeUsers()));restrictedMetric.setText(Long.toString(m.lockedUsers()));}}
 private void refresh(){refreshMetrics();var all=matching();while(page>0&&page*PAGE_SIZE>=all.size())page--;int from=Math.min(page*PAGE_SIZE,all.size()),to=Math.min(from+PAGE_SIZE,all.size());results.setAll(all.subList(from,to));refreshButtons();if(emptyLabel!=null){emptyLabel.setVisible(results.isEmpty());emptyLabel.setManaged(results.isEmpty());}if(sortButton!=null){sortButton.setText("Sort: "+label(sort));filterButton.setText(recentLoginOnly?"Logged in within 30 days":status==null?"All statuses":label(status));}}private void refreshButtons(){if(previousButton!=null){previousButton.setDisable(page==0);nextButton.setDisable((page+1)*PAGE_SIZE>=matching().size());}}private static String label(Enum<?> value){return value.name().toLowerCase().replace('_',' ');}
 public void dispose(){service.getUsers().removeListener(refreshListener);service.getUsers().forEach(u->u.statusProperty().removeListener(refreshListener));}
}
